-- gen601: 17 zone cambiate, 35 tessere
-- 9f00b4a0a6629c664d659dac78052959 (840372) → 550f5b8b33f6e9414729b839e47686c3 (845589)

  on conflict (key) do update set value=excluded.value;


-- il cancello, PRIMA di scrivere
select md5(string_agg(value, '' order by key)) as md5_ricomposto,
       length(string_agg(value, '' order by key)) as len_ricomposto,
       md5(string_agg(value, '' order by key)) = '550f5b8b33f6e9414729b839e47686c3' as combacia
from kv_store where key like 'tmp:gen601:p%';

update kv_store set value = (select string_agg(value, '' order by key) from kv_store where key like 'tmp:gen601:p%')
where key='app:jsx:src'
  and md5(value) = '9f00b4a0a6629c664d659dac78052959'
  and (select md5(string_agg(value, '' order by key)) from kv_store where key like 'tmp:gen601:p%') = '550f5b8b33f6e9414729b839e47686c3';

update kv_store set value = '{"len":845589,"ver":"gen-6.01"}'
where key='app:jsx:meta'
  and (select md5(value) from kv_store where key='app:jsx:src') = '550f5b8b33f6e9414729b839e47686c3';

delete from kv_store where key like 'tmp:gen601:p%';
